import sys,json # Trace a real bridge shell interface into refined local boundary coordinates.
import numpy as np # Construct an explicit displacement and dual-force transfer operator.
from fem import ROOT,RUN,write_json,sha # Reuse stable workspace identity and scientific evidence utilities.
sys.path.insert(0,str(ROOT/'render-runtime')) # Use the already validated mesh reader.
import pyvista as pv # Read actual native-derived whole-bridge fields.
source=ROOT/'model-repo/build/zhaqing-md-20261024/calculation/cases/LC02_G_Q_SERVICE/stress-coordinated.vtk';mesh=pv.read(source);u=np.asarray(mesh['displacement_mm']);reference=np.asarray(mesh.points)-u # Recover undeformed coordinates from the documented deformed-point result convention.
quads=np.where(mesh.celltypes==9)[0];assert len(quads)>0;centers=np.array([reference[mesh.get_cell(int(i)).point_ids].mean(axis=0) for i in quads]);chosen=int(quads[np.argmin(np.linalg.norm(centers-centers.mean(axis=0),axis=1))]);ids=np.asarray(mesh.get_cell(chosen).point_ids);corners=reference[ids] # Select a source-indexed central quadrilateral without inventing geometry.
parameters=np.array([(a,b) for a in np.linspace(0,1,9) for b in np.linspace(0,1,9)]);a,b=parameters.T;W=np.column_stack([(1-a)*(1-b),a*(1-b),a*b,(1-a)*b]);xyz=W@corners;displacement=W@u[ids] # Refine actual shell interface using explicit bilinear isoparametric shape functions.
boundary=np.where((a==0)|(a==1)|(b==0)|(b==1))[0];cells=np.array([[i*9+j,(i+1)*9+j,(i+1)*9+j+1,i*9+j+1] for i in range(8) for j in range(8)]) # Separate the true patch perimeter from unsolved local interior.
rng=np.random.default_rng(29);local_force=rng.normal(size=(len(boundary),3));parent_force=W[boundary].T@local_force;local_work=float(np.sum(local_force*displacement[boundary]));parent_work=float(np.sum(parent_force*u[ids]));error=abs(local_work-parent_work)/max(abs(parent_work),1.) # Verify displacement-force duality using a declared mathematical probe, not an invented physical load case.
affine=rng.normal(size=(3,3));offset=rng.normal(size=3);affine_error=float(np.max(np.abs(W@(corners@affine+offset)-(xyz@affine+offset))));partition=float(np.max(np.abs(W.sum(axis=1)-1))) # Verify partition of unity and exact affine-field transfer.
out=RUN/'global_local_transfer';out.mkdir(exist_ok=True);np.savez_compressed(out/'interface.npz',xyz=xyz,cells=cells,boundary=boundary,W=W,parent_point_indices=ids,parent_coordinates=corners,parent_displacement=u[ids],transferred_displacement=displacement) # Save complete actual geometry, field and reversible interface identity.
write_json(out/'verification.json',{'source':str(source),'source_sha256':sha(source),'source_cell_index':chosen,'source_element_id':int(mesh['source_element_id'][chosen]),'component_id':int(mesh['component_id'][chosen]),'local_nodes':81,'local_quads':64,'boundary_nodes':len(boundary),'partition_error':partition,'affine_field_error_mm':affine_error,'virtual_work_relative_error':error,'status':'PASS' if error<1e-12 and affine_error<1e-8 and partition<1e-12 else 'FAIL','scope':'Actual whole-bridge displacement interface transfer and dual virtual-work test only. Local constitutive solve, original loads, shell rotations and feedback coupling remain unvalidated.'}) # Keep tested transfer algebra separate from a completed coupled structural analysis.
print(json.dumps({'status':'PASS','virtual_work_relative_error':error,'source_element':int(mesh['source_element_id'][chosen])}),flush=True) # Report completed physical-source interface verification.
